use serde :: { Deserialize , Serialize } ; # [doc = " Information about a file or file range read operation"] # [derive (Debug , Clone , PartialEq , Eq , Serialize , Deserialize)] pub struct FileInfo { # [doc = " Starting line position of the read operation"] pub start_line : u64 , # [doc = " Ending line position of the read operation"] pub end_line : u64 , # [doc = " Total number of lines in the file"] pub total_lines : u64 , # [doc = " SHA-256 hash of the **full** file content."] # [doc = " Stored so callers have a stable hash that matches what a subsequent"] # [doc = " whole-file read produces (used by the external-change detector)."] pub content_hash : String , }